// Hand-rolled reusable grid barrier with sense reversal (NO cooperative groups,
// NO "stream" anywhere). Grid MUST be sized <= one-wave occupancy limit.
struct GridBarrier {
    unsigned int* arrive;   // global counter, 1 int
    unsigned int* sense;    // global generation/sense, 1 int
};

// Each block's thread 0 participates. Returns when all blocks have arrived.
__device__ void grid_barrier(GridBarrier b, int gridSize) {
    __syncthreads();                       // make block-local work visible to block's leader
    if (threadIdx.x == 0) {
        __threadfence();                   // publish this block's global writes before arriving
        unsigned int local_sense = *b.sense;          // read current phase
        unsigned int old = atomicInc(b.arrive, 0xffffffffu); // arrive; returns pre-inc value
        if (old == (unsigned int)(gridSize - 1)) {
            // last to arrive: reset counter and flip the sense to release everyone
            *b.arrive = 0;
            __threadfence();
            *b.sense = local_sense ^ 1u;
        } else {
            // spin until sense flips
            while (((volatile unsigned int*)b.sense)[0] == local_sense) { /* spin */ }
        }
        __threadfence();                   // see global writes published by peers
    }
    __syncthreads();                       // broadcast release to all threads in block
}

__global__ void multiphase(float* g, int n, GridBarrier bar, int gridSize, int phases) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    for (int p = 0; p < phases; ++p) {
        // phase write: each thread bumps its slot
        for (int i = tid; i < n; i += gridDim.x * blockDim.x) g[i] += 1.0f;
        grid_barrier(bar, gridSize);       // <-- reused many times
        // phase read: block 0 verifies all slots equal p+1 (cross-CTA visibility)
        if (blockIdx.x == 0 && threadIdx.x == 0) {
            // (cheap spot check)
            if (g[0] != (float)(p+1) || g[n-1] != (float)(p+1)) {
                printf("  MISMATCH at phase %d: g[0]=%f g[n-1]=%f\n", p, g[0], g[n-1]);
            }
        }
        grid_barrier(bar, gridSize);
    }
}

int main() {
    int dev=0; cudaSetDevice(dev);
    cudaDeviceProp prop; cudaGetDeviceProperties(&prop, dev);
    int bs=256, numBlocks=0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&numBlocks, multiphase, bs, 0);
    int grid = numBlocks*prop.multiProcessorCount;   // exactly one wave
    printf("grid=%d (one-wave limit), bs=%d\n", grid, bs);

    int n = 1<<16;
